mapper.select:


    systemLogOperation.deleted_flag = 'N'
    and systemLogOperation.remark = #{remark}
    and systemLogOperation.name like concat('%', #{name}, '%')
    and systemLogOperation.operation_type =
        #{operationType}

    and systemLogOperation.method = #{method}
    and systemLogOperation.request_method =
        #{requestMethod}

    and systemLogOperation.business_type =
        #{businessType}

    and systemLogOperation.operation_url =
        #{operationUrl}

    and systemLogOperation.operation_ip = #{operationIp}

    and systemLogOperation.operation_location
        = #{operationLocation}

    and systemLogOperation.operation_param =
        #{operationParam}

    and systemLogOperation.operation_result =
        #{operationResult}

    and systemLogOperation.status = #{status}
    and systemLogOperation.operation_person =
        #{operationPerson}

    and systemLogOperation.message like concat('%', #{message},
        '%')

    and systemLogOperation.organization_id =
        #{organizationId}

    and systemLogOperation.department_id =
        #{departmentId}


        and systemLogOperation.created_time between #{parameters.beginDate} and  #{parameters.endDate}


        and

            (
            systemLogOperation.remark like concat('%', #{item}, '%')
            or systemLogOperation.operation_person like concat('%', #{item}, '%')
            or  systemLogOperation.name like concat('%', #{item}, '%')
            or systemLogOperation.message like concat('%', #{item}, '%')
            )



order by systemLogOperation.created_time desc
